document.querySelector("#batch39 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/mahmoud-15455354.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف القرآن كائن حي\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>القرآن كائن حي</h3><p>يقدّم مصطفى محمود القرآن هنا بوصفه نصا تتصل أجزاؤه ولا تنفصل دلالاته في قراءة الآيات منفردة. وتعرض نبذة الطبعة اهتمامه بالنظام اللغوي والعددي وبا…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-2075295744.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف من أسرار القرآن\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>من أسرار القرآن</h3><p>تعرّف نبذة الطبعة بهذا الكتاب عبر موضوعات قرآنية وأسئلة يختارها مصطفى محمود للتأمل. ليست نقطة البدء تفسيرا متسلسلا للمصحف، بل محاولات للاقتراب من…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-15455357.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف الله والإنسان\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>الله والإنسان</h3><p>تقوم الفقرة المنشورة على مقابلة العلاقات الإنسانية المشروطة بما يطرأ عليها من تغير، بعلاقة الإنسان بالله كما يصوغها الكاتب. يستخدم مصطفى محمود صو…</p><small>مصطفى محمود</small></a>");
